(window.webpackJsonp=window.webpackJsonp||[]).push([[429],{758:function(n,e,t){"use strict";t.r(e);var r=t(33),a=Object(r.a)({},function(){var n=this,e=n.$createElement,t=n._self._c||e;return t("ContentSlotsDistributor",{attrs:{"slot-key":n.$parent.slotKey}},[t("h1",{attrs:{id:"fotometri-och-optik"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#fotometri-och-optik","aria-hidden":"true"}},[n._v("#")]),n._v(" Fotometri och optik")]),n._v(" "),t("p",[n._v("Fotometri är vetenskapen om mätning av ljus i termer av hur det mänskliga ögat\nupplever ljusstyrkan. Fotometri skiljer sig från radiometri som är vetenskapen om\nabsolutmätning av ljus. I fotometrin viktas ljuseffekten vid varje våglängd med en\nfunktion som modellerar ögats känslighet.")]),n._v(" "),t("p",[t("strong",[n._v("Ljus som fysikaliskt fenomen")]),n._v("\nDen elektromagnetiska strålning som kan ge upphov till synintryck kallas ofta synligt\nljus, trots att strålningen som sådan inte syns förrän den träffar de ljuskänsliga\nreceptorerna i våra ögon, antingen direkt från ljuskällan eller reflekterad från\nnågonting. De exakta gränserna för våglängdsområdet anges annorlunda i olika\nkällor och området kan som mest innefatta våglängderna 380-800 nanometer.\nGenom att ögat är känsligt för strålning i just detta intervall, kan vi se vår omgivning.\nNär ljuset från en ljuskälla reflekteras mot olika föremål i vår omgivning återkastas\nvissa våglängder av strålningen, och vi kan uppfatta föremålens färger och former\nmed ögonen.\nStrålningen inom det område som kan ge synintryck kan delas upp i olika våglängder\nmed t.ex. ett prisma, eller - som i regnbågen - i vattendroppar. När sådan strålning\nträffar en yta ser vi ett spektrum av kulörtoner från violett (kort våglängd) till rött (lång\nvåglängd). Ljusets brytning i ett prisma undersöktes och presenterades först av Isaac\nNewton som också konstaterade att strålningen som sådan saknar färg.\nÖvergångarna mellan olika färger är gradvisa men traditionellt brukar man dela upp\nspektrum i sju färger: Rött - orange - gult - grönt - blått - indigo - violett. Även andra\nindelningar förekommer, ett exempel visas i boxen nedan. Ljusstrålning med endast\nen våglängd kallas monokromatisk. Den uppträder bara i mycket speciella situationer.\nDet normala är i stället att den strålning som når våra ögon och där ger upphov till en\nfärgperception är blandning av många olika våglängder.")]),n._v(" "),t("p",[n._v("I många sammanhang används ordet ljus även om strålning utanför den synliga\ndelen av det elektromagnetiska spektrumet. För strålning med längre våglängd än\ninom det synliga området används benämningen infrarött ljus eller IR-ljus. Strålning\nmed kortare våglängd än den synliga kallas ultraviolett strålning eller UV-ljus.\nDen hastighet med vilken all elektromagnetisk strålning rör sig (per definition 299 792\n458 m/s i vakuum) benämns ljushastigheten. I kompakta material som glas rör sig\nljuset betydligt långsammare.")]),n._v(" "),t("p",[t("strong",[n._v("Att mäta ljus")]),n._v("\nFör planering av belysningsmiljöer och för specifikation av ljuskällor används\nfotometriska enheter som till exempel lumen för mätning av ljusflöde och lux för\nmätning av belysningsstyrka. För att fastställa de fotometriska värdena mäter man\nstrålningsenergin uppdelat på våglängd, och väger dessa värden mot en kurva för det\nmänskliga synsinnets känslighet i olika våglängdsområden. De fotometriska\nenheterna uttrycker alltså inte strålningens absoluta intensitet. Eftersom de bygger på\npunktvisa mätningar och medelvärden uttrycker de inte heller den enskilda\nmänniskans ljusupplevelse i den specifika situationen.")]),n._v(" "),t("p",[t("strong",[n._v("Se filmen om ljus nedan")]),n._v(" "),t("iframe",{attrs:{width:"560",height:"315",src:"https://www.youtube-nocookie.com/embed/cFwjMO7Kk38",frameborder:"0",allow:"accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""}})])])},[],!1,null,null,null);e.default=a.exports}}]);